#ifndef TOUCH_CALIBRATION_H
#define TOUCH_CALIBRATION_H

#include "ui_types.h"

/* -----------------------------------------------------------------------
 * touch_calibration.h
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * BJT2 Sound Modulating Toy — Touch Panel Calibration
 * Author: Tony (Display/UI subsystem)
 *
 * Converts raw ADC counts from the 4-wire resistive touch panel into
 * pixel coordinates in the panel frame (TOUCH_PANEL_W x TOUCH_PANEL_H,
 * the glass's own 320 x 240 landscape frame) using linear interpolation
 * clamped to the panel bounds; touch_panel_to_screen() then turns a
 * panel pixel into a screen pixel for the panel's rotation.
 *
 * The mapping formula for each axis is:
 *   pixel = (adc - ADC_MIN) * PANEL_DIM / (ADC_MAX - ADC_MIN)
 *
 * In words: the panel is two clear resistive sheets. tony_ui.c puts
 * 3.3 V across one sheet and reads the other with the 12-bit ADC (0 to
 * 4095 counts). A finger joins the two sheets, so the count rises evenly
 * from one edge of the glass to the other. ADC_MIN and ADC_MAX are the
 * counts measured at the two edges (TOUCH_X_MIN / TOUCH_X_MAX and
 * TOUCH_Y_MIN / TOUCH_Y_MAX in ui_types.h), so the fraction
 * (adc - ADC_MIN) / (ADC_MAX - ADC_MIN) is how far across the glass the
 * finger is, from 0 to 1, and that times the width in pixels is the
 * pixel. Example, X: (2025 - 365) * 320 / 3320 = 160, the middle of the
 * 320 px side. The code multiplies before it divides, so the integer
 * maths keeps its precision.
 *
 * Values outside the calibrated ADC range are clamped to prevent
 * unsigned integer underflow — a critical safety check since the
 * subtraction (adc - ADC_MIN) wraps silently if adc < ADC_MIN.
 * ----------------------------------------------------------------------- */

/**
 * touch_is_pressed
 * Returns true if the ADC values indicate a finger is on the panel.
 * Values below TOUCH_NO_PRESS_THRESHOLD_LOW or above
 * TOUCH_NO_PRESS_THRESHOLD_HIGH indicate no contact.
 *
 * @param adc_x  Raw ADC reading on the X axis.
 * @param adc_y  Raw ADC reading on the Y axis.
 * @return       true if a touch is detected, false otherwise.
 */
bool touch_is_pressed(uint16_t adc_x, uint16_t adc_y);

/**
 * touch_calibrate
 * Converts raw ADC counts to pixel coordinates in the panel frame.
 * Output is clamped to [0, TOUCH_PANEL_W-1] and [0, TOUCH_PANEL_H-1].
 * Caller must check touch_is_pressed() before calling this function.
 *
 * @param adc_x   Raw ADC count on the X axis (maps to the panel width).
 * @param adc_y   Raw ADC count on the Y axis (maps to the panel height).
 * @param out_px  Pointer to receive the calibrated X pixel coordinate.
 * @param out_py  Pointer to receive the calibrated Y pixel coordinate.
 */
void touch_calibrate(uint16_t adc_x, uint16_t adc_y,
                     uint16_t *out_px, uint16_t *out_py);

/**
 * touch_panel_to_screen
 * Converts a calibrated panel pixel (touch_calibrate's output, Y plate
 * still read bottom-to-top) into a screen pixel for the given panel
 * rotation, the same UI_ROT_* number the ILI9341 is set to, so the touch
 * always turns with the picture. Inputs past the panel edge are clamped.
 *
 * @param rotation  UI_ROT_VERTICAL_1 .. UI_ROT_HORIZONTAL_2 (ui_types.h).
 * @param cal_x     Calibrated panel X pixel (0..TOUCH_PANEL_W-1).
 * @param cal_y     Calibrated panel Y pixel (0..TOUCH_PANEL_H-1).
 * @param out_sx    Pointer to receive the screen X pixel.
 * @param out_sy    Pointer to receive the screen Y pixel.
 * @return          true on success; false (outputs untouched) for a NULL
 *                  output pointer or an unknown rotation.
 */
bool touch_panel_to_screen(uint8_t rotation, uint16_t cal_x, uint16_t cal_y,
                           uint16_t *out_sx, uint16_t *out_sy);

#endif /* TOUCH_CALIBRATION_H */
